#!/usr/bin/env python3
"""MTL: roll up a CSV of sales events according to a small pipeline DSL.

    python mtl.py --csv <path> --dsl <path-or-> [--out <path>]
                  [--tz <IANA>] [--timestamp-format <str>] [--strict]
                  [--param key=value ...]
"""

import argparse
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from mtl_core import csv_source, declarations, engine, output  # noqa: E402
from mtl_core.dsl_parser import parse_program  # noqa: E402
from mtl_core.errors import DslError, InputError, MtlError, report  # noqa: E402
from mtl_core.timestamps import TimestampParser  # noqa: E402


class _ArgumentParser(argparse.ArgumentParser):
    def error(self, message):
        raise InputError("invalid arguments: %s" % message)


def _parse_args(argv):
    parser = _ArgumentParser(prog="mtl.py", description=__doc__)
    parser.add_argument("--csv", required=True)
    parser.add_argument("--dsl", required=True)
    parser.add_argument("--out", default=None)
    parser.add_argument("--tz", default="UTC")
    parser.add_argument("--timestamp-format", dest="timestamp_format", default=None)
    parser.add_argument("--strict", action="store_true")
    parser.add_argument("--param", dest="params", action="append", nargs="+", default=[],
                        metavar="key=value")
    args = parser.parse_args(argv)
    pairs = [pair for group in args.params for pair in group]
    args.params = declarations.parse_cli_params(pairs)
    if args.params is None:
        raise InputError("invalid arguments: --param expects key=value")
    return args


def _read_dsl(source):
    try:
        if source == "-":
            data = sys.stdin.buffer.read()
        else:
            with open(source, "rb") as handle:
                data = handle.read()
    except OSError as exc:
        raise InputError("cannot read DSL %r: %s" % (source, exc.strerror or exc))
    try:
        return data.decode("utf-8-sig")
    except UnicodeDecodeError:
        raise InputError("DSL %r is not valid UTF-8" % source)


def _write(destination, text):
    data = text.encode("utf-8")
    if destination is None or destination == "-":
        sys.stdout.buffer.write(data)
        sys.stdout.buffer.flush()
        return
    try:
        with open(destination, "wb") as handle:
            handle.write(data)
    except OSError as exc:
        raise InputError("cannot write output %r: %s" % (destination, exc.strerror or exc))


def run(argv):
    args = _parse_args(argv)
    dsl_text = _read_dsl(args.dsl)
    csv_text = csv_source.read_csv_text(args.csv)
    ts_parser = TimestampParser(args.tz, args.timestamp_format)
    program = parse_program(dsl_text)
    schema = declarations.resolve_schema(program)
    params = declarations.bind_params(program, args.params, ts_parser)
    dataset = csv_source.build_dataset(csv_text, ts_parser,
                                       schema.physical if schema is not None else None)
    result = engine.execute(program, dataset, schema, params, ts_parser)
    _write(args.out, output.render(result))


def main(argv=None):
    try:
        run(sys.argv[1:] if argv is None else argv)
    except MtlError as err:
        return report(err, sys.stderr)
    except RecursionError:
        return report(DslError("DSL nesting too deep"), sys.stderr)
    except Exception as exc:  # last-resort guard: never leak a traceback
        from mtl_core.errors import ExecutionError
        return report(ExecutionError("internal error: %s" % exc), sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())
"""Core modules of the MTL rollup tool (see DESIGN.md)."""
"""Failure categories.

Secret: how failure categories map to exit codes and how the diagnostic
line is formatted.
"""


class MtlError(Exception):
    """Base class of all user-facing failures."""

    _label = "runtime_error"
    _code = 4


class DslError(MtlError):
    """The DSL program is syntactically or structurally invalid."""

    _label = "bad_dsl"
    _code = 1


class TypeCheckError(MtlError):
    """A value or expression has an unacceptable type."""

    _label = "type_error"
    _code = 2


class InputError(MtlError):
    """Inputs could not be read (files, CSV structure, CLI arguments)."""

    _label = "bad_io"
    _code = 3


class ExecutionError(MtlError):
    """Evaluation failed at run time (division by zero, non-finite values)."""

    _label = "runtime_error"
    _code = 4


def report(error, stream):
    """Write the one-line diagnostic for `error` and return its exit code."""
    message = " ".join(str(error).split()) or error.__class__.__name__
    stream.write("ERROR:%s:%s\n" % (error._label, message))
    stream.flush()
    return error._code
"""CSV event source.

Secret: the CSV dialect and encoding, the fixed schema of the known event
columns (or the physical fields of a declared schema), how cells become
typed values, and how types of extra columns are inferred.
"""

import csv
import io
import re

from . import valuetypes as T
from .dataset import Dataset
from .errors import InputError, TypeCheckError

_KNOWN = {
    "timestamp": T.TIMESTAMP,
    "location": T.STRING,
    "item": T.STRING,
    "price": T.FLOAT,
    "quantity": T.FLOAT,
    "unit": T.STRING,
    "category": T.STRING,
}
_INT_RE = re.compile(r"^[+-]?\d+$")
_FLOAT_RE = re.compile(r"^[+-]?(\d+\.?\d*([eE][+-]?\d+)?|\.\d+([eE][+-]?\d+)?)$")


def read_csv_text(path):
    """Read the raw file; I/O problems are reported as InputError."""
    try:
        with open(path, "rb") as handle:
            data = handle.read()
    except OSError as exc:
        raise InputError("cannot read CSV %r: %s" % (path, exc.strerror or exc))
    try:
        return data.decode("utf-8-sig")
    except UnicodeDecodeError:
        raise InputError("CSV %r is not valid UTF-8" % path)


def _split(text, required):
    try:
        rows = list(csv.reader(io.StringIO(text, newline=""), strict=True))
    except csv.Error as exc:
        raise InputError("malformed CSV: %s" % exc)
    rows = [r for r in rows if r and not (len(r) == 1 and r[0].strip() == "")]
    if not rows:
        raise InputError("CSV has no header row")
    header = [h.strip() for h in rows[0]]
    if any(h == "" for h in header):
        raise InputError("CSV header contains an empty column name")
    if len(set(header)) != len(header):
        raise InputError("CSV header contains duplicate column names")
    missing = [c for c in required if c not in header]
    if missing:
        raise InputError("CSV is missing required column(s): %s" % ", ".join(missing))
    body = rows[1:]
    for lineno, row in enumerate(body, start=2):
        if len(row) != len(header):
            raise InputError("CSV record %d has %d fields, expected %d"
                             % (lineno, len(row), len(header)))
    return header, body


def _parse_float(text):
    try:
        return float(text.strip())
    except ValueError:
        raise ValueError(text)


def _parse_bool(text):
    lowered = text.strip().lower()
    if lowered not in ("true", "false"):
        raise ValueError(text)
    return lowered == "true"


def _infer(cells, ts_parser):
    present = [c.strip() for c in cells if c.strip() != ""]
    if not present:
        return T.STRING
    if all(_INT_RE.match(c) for c in present):
        return T.INT
    if all(_FLOAT_RE.match(c) for c in present):
        return T.FLOAT
    if all(c in ("true", "false") for c in present):
        return T.BOOL
    if all(ts_parser.looks_like_timestamp(c) for c in present):
        return T.TIMESTAMP
    return T.STRING


def _converter(col_type, ts_parser, required):
    def nullable(fn):
        def convert(cell):
            if cell.strip() == "":
                if required:
                    raise ValueError("empty value")
                return None
            return fn(cell)
        return convert

    if col_type == T.STRING:
        return lambda cell: cell
    if col_type == T.INT:
        return nullable(lambda c: int(c.strip()))
    if col_type == T.FLOAT:
        return nullable(_parse_float)
    if col_type == T.BOOL:
        return nullable(_parse_bool)
    return nullable(ts_parser.parse)


def build_dataset(text, ts_parser, declared=None):
    """Convert raw CSV text into a typed Dataset.

    declared: optional name -> type of schema fields that must be present;
    without it the fixed event columns are required.
    """
    header, body = _split(text, _KNOWN if declared is None else declared)
    declared = declared or {}
    types = []
    converters = []
    for pos, name in enumerate(header):
        required = name in _KNOWN
        if name in declared:
            col_type = declared[name]
        elif required:
            col_type = _KNOWN[name]
        else:
            col_type = _infer([r[pos] for r in body], ts_parser)
        types.append(col_type)
        converters.append(_converter(col_type, ts_parser, required))
    rows = []
    for lineno, raw in enumerate(body, start=2):
        row = []
        for name, col_type, convert, cell in zip(header, types, converters, raw):
            try:
                value = convert(cell)
            except (ValueError, OverflowError):
                raise TypeCheckError("CSV record %d: column %r value %r is not a valid %s"
                                     % (lineno, name, cell, T.type_name(col_type)))
            row.append(value)
        rows.append(row)
    return Dataset.from_rows(header, types, rows)


def load_csv(path, ts_parser):
    return build_dataset(read_csv_text(path), ts_parser)
"""In-memory table.

Secret: how rows and the column schema are stored.  Callers see only
column names/types and read-only records.
"""


class Record:
    """Read-only view of one row."""

    __slots__ = ("_index", "_values")

    def __init__(self, index, values):
        self._index = index
        self._values = values

    def get(self, name):
        return self._values[self._index[name]]


class Dataset:
    def __init__(self, names, types, rows):
        self._names = list(names)
        self._types = list(types)
        self._index = {n: i for i, n in enumerate(self._names)}
        self._rows = rows

    @classmethod
    def from_rows(cls, names, types, rows):
        """Build from column names, their types and value sequences in that order."""
        return cls(names, types, [list(r) for r in rows])

    def has(self, name):
        return name in self._index

    def type_of(self, name):
        return self._types[self._index[name]]

    def __len__(self):
        return len(self._rows)

    def records(self):
        index = self._index
        for row in self._rows:
            yield Record(index, row)

    def filter(self, predicate):
        """New dataset holding the rows for which predicate(record) is True."""
        index = self._index
        kept = [row for row in self._rows if predicate(Record(index, row))]
        return Dataset(self._names, self._types, kept)

    def derive(self, name, value_type, compute):
        """New dataset with column `name` (added or replaced) = compute(record)."""
        index = self._index
        values = [compute(Record(index, row)) for row in self._rows]
        names = list(self._names)
        types = list(self._types)
        if name in index:
            pos = index[name]
            types[pos] = value_type
            rows = []
            for row, value in zip(self._rows, values):
                row = list(row)
                row[pos] = value
                rows.append(row)
        else:
            names.append(name)
            types.append(value_type)
            rows = [row + [value] for row, value in zip(self._rows, values)]
        return Dataset(names, types, rows)
"""Pipeline execution.

Secret: the execution strategy -- schema-level and @stage(pre) calculated
fields materialise first, row steps then run in program order, rollup
clauses act on the final rows, result rows are put in their canonical order
and @stage(post_agg) calcs are evaluated over that order; everything is
type-checked before any row is touched; rows are bucketed by (window, group
key).
"""

import re
from collections import namedtuple

from . import program as P
from . import valuetypes as T
from .aggregates import make_aggregate, result_type
from .errors import DslError, TypeCheckError
from .expressions import coerce, compile_expression, is_assignable
from .windowing import TumblingWindow

ResultRow = namedtuple("ResultRow", "window_start window_end keys values")
_WINDOW_FIELDS = ("window_start", "window_end")


class ResultSet:
    """Rollup outcome handed to the renderer.

    windowed:      whether rows carry window bounds
    group_columns: group_by column names, in declared order (may be empty)
    group_types:   the value type of each group column
    aliases:       aggregate aliases
    scalar:        True when there is neither window nor group_by
    rows:          ResultRow list in output order (keys align with
                   group_columns, values by alias and calc name)
    calc_names:    post-aggregation calc names
    calc_types:    the value type of each post-aggregation calc
    """

    def __init__(self, windowed, group_columns, group_types, aliases, scalar, rows,
                 calc_names=(), calc_types=()):
        self.windowed = windowed
        self.group_columns = tuple(group_columns)
        self.group_types = tuple(group_types)
        self.aliases = tuple(aliases)
        self.scalar = scalar
        self.rows = rows
        self.calc_names = tuple(calc_names)
        self.calc_types = tuple(calc_types)


class _Schema:
    """Static view of column types as the program evolves them."""

    def __init__(self, base):
        self._base = base
        self._overrides = {}

    def has(self, name):
        return name in self._overrides or self._base.has(name)

    def type_of(self, name):
        if name in self._overrides:
            return self._overrides[name]
        return self._base.type_of(name)

    def define(self, name, value_type):
        self._overrides[name] = value_type


class _Names:
    """A plain name -> type mapping with the has/type_of protocol."""

    def __init__(self):
        self._types = {}

    def has(self, name):
        return name in self._types

    def type_of(self, name):
        return self._types[name]

    def define(self, name, value_type):
        self._types[name] = value_type


class _OutputRecord:
    """One result row as seen by post-aggregation calcs."""

    __slots__ = ("data", "position", "table")

    def __init__(self, data, position, table):
        self.data = data
        self.position = position
        self.table = table

    def get(self, name):
        return self.data[name]


def _require_column(schema, name, context):
    if not schema.has(name):
        raise TypeCheckError("unknown column %r in %s" % (name, context))
    return schema.type_of(name)


def _sort_key(value):
    # Nulls sort first; values within one column share a type, so Python's
    # ordering gives numeric, code-point and chronological order respectively.
    return (0, 0) if value is None else (1, value)


def _check_declared(name, declared, compiled, what):
    if not is_assignable(declared, compiled.type):
        raise TypeCheckError("%s %r is declared %s but its expression is %s"
                             % (what, name, T.type_name(declared), T.type_name(compiled.type)))
    return coerce(declared, compiled)


def _window(program, params):
    spec = program.window
    if spec.param is None:
        return TumblingWindow(spec.amount, spec.unit)
    if spec.param not in params:
        raise DslError("unknown parameter %r" % spec.param)
    value_type, value = params[spec.param]
    m = re.match(r"^\s*(\d+)\s*([mhd])\s*$", value) if T.is_string(value_type) else None
    if not m or int(m.group(1)) <= 0:
        raise TypeCheckError("window parameter %r must be a duration like '1h', got %r"
                             % (spec.param, value))
    return TumblingWindow(int(m.group(1)), m.group(2))


def execute(program, dataset, schema_def=None, params=None, ts_parser=None):
    params = params or {}
    schema = _Schema(dataset)
    row_ops = []

    def compile_for_rows(expr, unknown=None):
        return compile_expression(expr, schema, params, unknown=unknown, ts_parser=ts_parser)

    # Schema-level calculated fields.
    if schema_def is not None:
        def schema_unknown(name):
            return DslError("schema field references unknown field %r" % name)
        for field in schema_def.calcs:
            compiled = compile_for_rows(field.expression, schema_unknown)
            evaluate = _check_declared(field.name, field.type, compiled, "schema field")
            schema.define(field.name, field.type)
            row_ops.append(("derive", field.name, field.type, evaluate))

    # @stage(pre) calcs.
    aliases = [item.alias for item in program.aggregate.items]
    pre_names = [c.name for c in program.pre_calcs]
    post_names = [c.name for c in program.post_calcs]
    apply_targets = {s.column for s in program.steps if isinstance(s, P.Apply)}
    for index, calc in enumerate(program.pre_calcs):
        if schema.has(calc.name) or calc.name in apply_targets:
            raise DslError("calculated field %r collides with an existing field" % calc.name)
        later = set(pre_names[index + 1:])

        def pre_unknown(name, later=later):
            if name in aliases or name in post_names:
                return DslError("@stage(pre) calc cannot use aggregate output %r" % name)
            if name in later:
                return DslError("calc references %r before it is declared" % name)
            return TypeCheckError("unknown column %r" % name)
        compiled = compile_for_rows(calc.expression, pre_unknown)
        evaluate = _check_declared(calc.name, calc.type, compiled, "calc")
        schema.define(calc.name, calc.type)
        row_ops.append(("derive", calc.name, calc.type, evaluate))

    # Part 1 row steps.
    for step in program.steps:
        if isinstance(step, P.Filter):
            compiled = compile_for_rows(step.predicate)
            if not T.is_bool(compiled.type):
                raise TypeCheckError("filter expression must be boolean, got %s"
                                     % T.type_name(compiled.type))
            row_ops.append(("filter", compiled.evaluate))
        else:
            compiled = compile_for_rows(step.expression)
            schema.define(step.column, compiled.type)
            row_ops.append(("derive", step.column, compiled.type, compiled.evaluate))

    group_columns = program.group_by.columns if program.group_by else ()
    group_types = [_require_column(schema, c, "group_by") for c in group_columns]

    window = None
    if program.window is not None:
        ts_type = _require_column(schema, "timestamp", "window")
        if not T.is_timestamp(ts_type):
            raise TypeCheckError("window requires 'timestamp' to be a timestamp, got %s"
                                 % T.type_name(ts_type))
        window = _window(program, params)

    aggregates = []
    output_names = _Names()
    if window is not None:
        for name in _WINDOW_FIELDS:
            output_names.define(name, T.TIMESTAMP)
    for name, value_type in zip(group_columns, group_types):
        output_names.define(name, value_type)
    for item in program.aggregate.items:
        input_type = None
        if item.column is not None:
            input_type = _require_column(schema, item.column, "aggregate")
        aggregates.append((item, make_aggregate(item.function, input_type)))
        output_names.define(item.alias, result_type(item.function, input_type))

    # @stage(post_agg) calcs.
    post_calcs = []
    for index, calc in enumerate(program.post_calcs):
        if output_names.has(calc.name):
            raise DslError("calculated field %r collides with another output field" % calc.name)
        later = set(post_names[index + 1:])

        def post_unknown(name, later=later):
            if name in later:
                return DslError("calc references %r before it is declared" % name)
            return TypeCheckError("@stage(post_agg) calc references %r, which is not a "
                                  "group key, window bound, aggregate or earlier calc" % name)
        compiled = compile_expression(calc.expression, output_names, params, row_relative=True,
                                      unknown=post_unknown, ts_parser=ts_parser)
        evaluate = _check_declared(calc.name, calc.type, compiled, "calc")
        output_names.define(calc.name, calc.type)
        post_calcs.append((calc.name, evaluate))

    for op in row_ops:
        if op[0] == "filter":
            predicate = op[1]
            dataset = dataset.filter(lambda r, p=predicate: p(r) is True)
        else:
            dataset = dataset.derive(op[1], op[2], op[3])

    buckets = {}
    for record in dataset.records():
        bounds = window.bounds(record.get("timestamp")) if window else (None, None)
        key = (bounds, tuple(record.get(c) for c in group_columns))
        buckets.setdefault(key, []).append(record)

    scalar = window is None and not group_columns
    if scalar and not buckets:
        buckets[((None, None), ())] = []

    rows = []
    for (bounds, keys), records in buckets.items():
        values = {}
        for item, aggregate in aggregates:
            if item.column is None:
                inputs = [True] * len(records)
            else:
                inputs = [r.get(item.column) for r in records]
            values[item.alias] = aggregate.compute(inputs)
        rows.append(ResultRow(bounds[0], bounds[1], keys, values))
    rows.sort(key=lambda r: (_sort_key(r.window_start), tuple(_sort_key(k) for k in r.keys)))

    if post_calcs:
        table = []
        for position, row in enumerate(rows):
            data = dict(row.values)
            data.update(zip(group_columns, row.keys))
            if window is not None:
                data["window_start"] = row.window_start
                data["window_end"] = row.window_end
            table.append(_OutputRecord(data, position, table))
        for name, evaluate in post_calcs:
            for record in table:
                record.data[name] = evaluate(record)
        for row, record in zip(rows, table):
            for name, _ in post_calcs:
                row.values[name] = record.data[name]

    post = program.post_calcs
    return ResultSet(window is not None, group_columns, group_types, aliases, scalar, rows,
                     [c.name for c in post], [c.type for c in post])
"""Abstract syntax of an MTL program.

This is the shared vocabulary between the parser and the engine; it reveals
nothing about concrete syntax or about how programs are executed.
"""

from collections import namedtuple

# Expressions
Literal = namedtuple("Literal", "kind value")        # kind: int|float|string|bool
ColumnRef = namedtuple("ColumnRef", "name")
Unary = namedtuple("Unary", "op operand")            # op: ! - +
Binary = namedtuple("Binary", "op left right")       # op: | & == != < <= > >= in + - * / %
Call = namedtuple("Call", "name args")               # transform / function call
Param = namedtuple("Param", "name")                  # param("<name>")
Cast = namedtuple("Cast", "operand type")            # cast(<expr> as <type>)

# Statements
Filter = namedtuple("Filter", "predicate")
Apply = namedtuple("Apply", "expression column")
GroupBy = namedtuple("GroupBy", "columns")
Window = namedtuple("Window", "amount unit param")   # unit: m|h|d; param: name or None
Window.__new__.__defaults__ = (None,)
AggregateItem = namedtuple("AggregateItem", "function column alias")  # column None means *
Aggregate = namedtuple("Aggregate", "items")
Calc = namedtuple("Calc", "name expression type stage")               # stage: pre|post_agg

# Declarations
FieldDef = namedtuple("FieldDef", "name type expression")   # expression None => physical
SchemaDef = namedtuple("SchemaDef", "name base fields")     # base: schema name or None
ParamDef = namedtuple("ParamDef", "name type default")      # type/default may be None

STAGE_PRE = "pre"
STAGE_POST = "post_agg"


class Program:
    """A validated pipeline: row steps in order plus the rollup clauses."""

    def __init__(self, steps, group_by, window, aggregate, calcs=(), params=(),
                 schemas=None, schema_name=None, name=None):
        self.steps = tuple(steps)        # Filter / Apply, in execution order
        self.group_by = group_by         # GroupBy or None
        self.window = window             # Window or None
        self.aggregate = aggregate       # Aggregate
        self.calcs = tuple(calcs)        # Calc, in declaration order
        self.params = tuple(params)      # ParamDef, in declaration order
        self.schemas = dict(schemas or {})  # name -> SchemaDef
        self.schema_name = schema_name   # schema named by `using`, or None
        self.name = name                 # pipeline name, or None (bare program)

    @property
    def pre_calcs(self):
        return tuple(c for c in self.calcs if c.stage == STAGE_PRE)

    @property
    def post_calcs(self):
        return tuple(c for c in self.calcs if c.stage == STAGE_POST)

